import json
import re
import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()

    processed_data = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            processed_data[k] = float(v * 2)
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item * 2))
                elif isinstance(item, str) and re.match(r'^-?\d+\.?\d*$', item):
                    new_list.append(str(float(item) * 2))
                else:
                    new_list.append(item)
            processed_data[k] = new_list
        elif isinstance(v, str) and re.match(r'^-?\d+\.?\d*$', v):
            processed_data[k] = str(float(v) * 2)
        else:
            processed_data[k] = v

    return pd.DataFrame([processed_data])
