### code
```python
import json
from glob import glob

def task_func(directory, string):
    def contains_string(data, target):
        if isinstance(data, str):
            return data == target
        elif isinstance(data, dict):
            return any(contains_string(v, target) for v in data.values())
        elif isinstance(data, list):
            return any(contains_string(item, target) for item in data)
        return False

    matched_files = []
    search_path = f"{directory}/**/*.json"
    files = glob(search_path, recursive=True)

    for file_path in files:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
                if contains_string(data, string):
                    matched_files.append(file_path)
        except (json.JSONDecodeError, IOError):
            continue

    return matched_files
